import { handleSignedObject } from "./src/server/cloudflare/storage-access";
import {
  consumeGenerationQueue,
  type GenerationMessage,
} from "./src/server/cloudflare/generation-queue";
// Generated by the OpenNext build before Wrangler bundles this entry point.
// @ts-ignore -- the generated module does not exist in a fresh checkout
import handler from "./.open-next/worker.js";

export default {
  fetch(request, env, ctx) {
    if (new URL(request.url).pathname === "/api/v1/storage/object")
      return handleSignedObject(request, env);
    return handler.fetch(request, env, ctx);
  },

  async queue(batch, env, ctx) {
    await consumeGenerationQueue(batch, env, (request) =>
      handler.fetch(request, env, ctx),
    );
  },
} satisfies ExportedHandler<CloudflareEnv, GenerationMessage>;
